// Native popovers escape card clipping and stacking contexts, including dialogs.
(()=>{
 let active=null,pinned=false,timer;
 const buttonOf=target=>target instanceof Element?target.closest('.info9>button'):null;
 function place(){
  if(!active)return;
  if(!active.button.isConnected){hide();return;}
  const {button,pop}=active,r=button.getBoundingClientRect();
  if(r.bottom<0||r.top>innerHeight){hide();return;}
  const box=pop.getBoundingClientRect(),gap=8,edge=12;
  pop.style.left=Math.max(edge,Math.min(r.left,innerWidth-box.width-edge))+'px';
  const below=r.bottom+gap,above=r.top-gap-box.height;
  pop.style.top=Math.max(edge,Math.min(below+box.height<=innerHeight-edge?below:above,innerHeight-box.height-edge))+'px';
 }
 function hide(){
  clearTimeout(timer);if(!active)return;
  active.pop.hidePopover();active.button.setAttribute('aria-expanded','false');
  active=null;pinned=false;
 }
 function show(button){
  clearTimeout(timer);if(active?.button===button)return;
  hide();const pop=button.parentElement.querySelector('.info-pop9');if(!pop)return;
  pop.setAttribute('popover','manual');active={button,pop};
  pop.showPopover();button.setAttribute('aria-expanded','true');place();
 }
 function scheduleHide(){clearTimeout(timer);timer=setTimeout(()=>{if(!pinned&&active&&!active.pop.matches(':hover')&&document.activeElement!==active.button)hide();},140);}
 document.addEventListener('pointerover',event=>{
  const button=buttonOf(event.target);if(button)show(button);
  else if(active?.pop.contains(event.target))clearTimeout(timer);
 });
 document.addEventListener('pointerout',event=>{
  if(active&&(active.button.contains(event.target)||active.pop.contains(event.target))){
   if(active.button.contains(event.relatedTarget)||active.pop.contains(event.relatedTarget))return;
   scheduleHide();
  }
 });
 document.addEventListener('focusin',event=>{const button=buttonOf(event.target);if(button)show(button);});
 document.addEventListener('focusout',event=>{if(buttonOf(event.target))scheduleHide();});
 document.addEventListener('click',event=>{
  const button=buttonOf(event.target);
  if(button){event.preventDefault();event.stopImmediatePropagation();if(active?.button===button&&pinned)hide();else{show(button);pinned=true;}return;}
  if(active&&!active.pop.contains(event.target))hide();
 },true);
 document.addEventListener('keydown',event=>{if(event.key==='Escape'&&active){event.preventDefault();event.stopImmediatePropagation();hide();}},true);
 document.addEventListener('scroll',place,true);window.addEventListener('resize',place);
 new MutationObserver(()=>{if(active&&!active.button.isConnected)hide();}).observe(document.body,{childList:true,subtree:true});
})();


